import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
params={'db':'pubmed','term':'(Malawi[Title/Abstract]) AND (HBV OR hepatitis B) AND (HIV) AND (lamivudine OR resistance OR subgenotype)','retmode':'json','retmax':20}
r=requests.get(u,params=params,timeout=20); print('status',r.status_code); ids=r.json()['esearchresult']['idlist']; print('ids',ids)
if ids:
 s=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
 for i in ids: print(i,s[i].get('title'),s[i].get('pubdate'),s[i].get('fulljournalname'))
